/**
 * Release facts the site renders, derived from src/data/release-facts.json.
 *
 * Nothing here is typed by hand. release-facts.json is generated by `python scripts/site_facts.py`
 * from pyproject.toml, src/repo_ai/__init__.py, the latest release tag and
 * docs/engineering/evidence-matrix.json; PyPI counts as published only when that matrix records a
 * verified read (sha256 and date) of this distribution. `--check` fails when the file is stale.
 */
import { facts } from './data/facts';

export const site = {
  /** The release the install commands point at (the verified PyPI release when there is one). */
  version: facts.site_version,
  /** PyPI distribution name; the command it installs is `command`. */
  distribution: facts.package.distribution,
  command: facts.package.command,
  /** true only from a verified read recorded in the evidence matrix. */
  pypiPublished: facts.pypi.published === true,
  /** Canonical repository URL. Only rendered as a link when `repoPublic` is true. */
  githubRepo: facts.repository.url,
  repoPublic: facts.repository.public === true,
  /** Date the evidence ledger (and with it the facts on the site) was last checked. */
  factsAsOf: facts.facts_as_of,
} as const;

export const pypi = facts.pypi;
export const releaseTag = facts.release.tag;
export const releaseUrl = facts.release.url;

const wheelFile = `${site.distribution.replace(/-/g, '_')}-${site.version}-py3-none-any.whl`;
export const wheelName = wheelFile;
export const wheelUrl = `${site.githubRepo}/releases/download/v${site.version}/${wheelName}`;

/** The primary install command for the current distribution state. */
export const installCommand = site.pypiPublished ? `pipx install ${site.distribution}` : `python -m pip install ${wheelUrl}`;

/** Alternative commands shown under the primary one. */
export const installAlternatives: { label: string; command: string }[] = site.pypiPublished
  ? [{ label: 'pip', command: `python -m pip install ${site.distribution}` }]
  : [{ label: 'pipx, from the same wheel', command: `pipx install ${wheelUrl}` }];

export const installNote = site.pypiPublished
  ? `repo-ai ${site.version} is published on PyPI as ${site.distribution}; the command is ${site.command}.`
  : `repo-ai ${site.version} is not on PyPI yet. The command installs the wheel attached to the GitHub release; pip still fetches the one runtime dependency (pathspec, plus tomli on Python 3.10) from PyPI.`;

export const sourceLabel = site.repoPublic ? 'Source on GitHub' : 'Source: coming soon';
